  // No clear route: yield instead of replaying the same circular walk.
  // Planning resumes automatically when this short idle step finishes.
  v.path = [];
  v.step = { kind: 'idle', dur: 5, activity: 'waiting for the footpath to clear' };
  v.inside = false;
  v.crowdRecovery = 0;
  v.walkProgress = null;
}

