    if(newly.length)this.log('Power interrupted at '+newly.map(id=>c.powerGrid.customers[id].name).join(', ')+'.');
    if(recovered.length)this.log('Power restored to '+recovered.map(id=>c.powerGrid.customers[id].name).join(', ')+'.');
  }
