  if ((bakery.out.pie || 0) < Math.ceil(16*Math.max(1,this.villagers.length/38)) && (s.flour || 0) >= 1 && (s.lamb || 0) >= 1 && (s.veg || 0) >= 1) { s.flour--; s.lamb--; s.veg--; bakery.out.pie = (bakery.out.pie || 0) + 4; this.stats.baked += 4; }
}
