householdMembers(coordinate){return familyMembers(this.villagers,coordinate);}
describe(v) {
  const last = v.lastMeal ? `${v.lastMeal.name} at ${fmt(v.lastMeal.at)}${v.lastMeal.day !== this.day ? ' yesterday' : ''}` : 'nothing yet today';
